/**
 * Generate PDF from the ResourcesPDFTemplate component
 * @param elementId - The ID of the HTML element to convert to PDF (default: 'pdf-content')
 * @param filename - The name of the PDF file to download (default: 'resources.pdf')
 * @returns Promise that resolves when PDF is generated
 */
export const generateResourcesPDF = async (
  elementId: string = 'pdf-content',
  filename: string = 'resources.pdf'
): Promise<void> => {
  const element = document.getElementById(elementId);
  if (!element) {
    console.error(`Element with id '${elementId}' not found`);
    return;
  }

  try {
    // Get all pages within the PDF content
    const pages = element.querySelectorAll('[style*="height: 842px"]');
    const pdf = new jsPDF({
      orientation: 'portrait',
      unit: 'px',
      format: [595, 842], // A4 size in pixels at 72 DPI
    });

    for (let i = 0; i < pages.length; i++) {
      const page = pages[i] as HTMLElement;
      
      // Capture the page as canvas
      const canvas = await html2canvas(page, {
        scale: 2, // Higher scale for better quality
        useCORS: true,
        logging: false,
        backgroundColor: '#ffffff',
      });

      // Convert canvas to image
      const imgData = canvas.toDataURL('image/png');
      
      // Add new page if not the first page
      if (i > 0) {
        pdf.addPage();
      }

      // Add image to PDF (fit to page)
      const imgWidth = 595;
      const imgHeight = 842;
      pdf.addImage(imgData, 'PNG', 0, 0, imgWidth, imgHeight);
    }

    // Save the PDF
    pdf.save(filename);
  } catch (error) {
    console.error('Error generating PDF:', error);
    throw error;
  }
};
